// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getHighlightsList, getHighlight, putHighlights } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const take = "100";

    const highlightsGetResponse = await getHighlightsList(client, {});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGetResponse, "response.nextCursor"), 'default page needs no cursor').toBeNull();

    const highlightsGet1Response = await getHighlightsList(client, {"color": ["purple"]}, 400);
    expect(highlightsGet1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet1Response, "response"), 'colour rejection names the allowed colours').toBe("Invalid color. Allowed colors are: yellow, green, blue, red.");

    const highlightsGet2Response = await getHighlightsList(client, {"take": ["0"]}, 400);
    expect(highlightsGet2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet2Response, "response"), 'take below its floor is rejected').toBe("take must be a whole number between 1 and 100.");

    const highlightsGet3Response = await getHighlightsList(client, {"take": ["101"]}, 400);
    expect(highlightsGet3Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet3Response, "response"), 'take above its ceiling is rejected').toBe("take must be a whole number between 1 and 100.");

    const highlightsGet4Response = await getHighlightsList(client, {"take": ["abc"]}, 400);
    expect(highlightsGet4Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet4Response, "response"), 'a non-numeric take is rejected').toBe("take must be a whole number between 1 and 100.");

    const highlightsGet5Response = await getHighlightsList(client, {"take": [take]});
    expect(highlightsGet5Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet5Response, "response.highlights").length, 'take at its ceiling returns at most that many rows').toBeLessThanOrEqual(100);

    const highlightsGet6Response = await getHighlightsList(client, {"cursor": ["0"]}, 400);
    expect(highlightsGet6Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet6Response, "response"), 'a cursor below its floor is rejected').toBe("cursor must be the id of a highlight.");

    const highlightsGet7Response = await getHighlightsList(client, {"cursor": ["abc"]}, 400);
    expect(highlightsGet7Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet7Response, "response"), 'a non-numeric cursor is rejected').toBe("cursor must be the id of a highlight.");

    const highlightsPutRequestBody: string = `{
        "color": "yellow",
        "comment": "Testbot unsupported method probe"
    }`;
    const highlightsPutResponse = await putHighlights(client, highlightsPutRequestBody, 405);
    expect(highlightsPutResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(highlightsPutResponse, "response"), 'PUT on the collection route is not allowed').toBe("Method not allowed.");

    const highlights1GetResponse = await getHighlight(client, 1, 405);
    expect(highlights1GetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(highlights1GetResponse, "response"), 'GET on the item route is not allowed').toBe("Method not allowed.");
});
